      "refute_if": "2024-11-28 is not flagged as a holiday or the prior Thursdays are also holidays."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather (precipitation, cold, snow) on 2024-11-28 reduced trip demand relative to the prior Thursdays.",
      "support_if": "2024-11-28 shows measurable precipitation (>5 mm), snowfall (>0 mm), or max temperature below 5 °C while the prior Thursdays are mild/dry.",
      "refute_if": "Weather on 2024-11-28 is similar to or better than the prior Thursdays."
    },
    {
      "id": "H3",
      "kind": "fare_mix",
      "statement": "The mix of trip distances or fares shifted on 2024-11-28 (e.g., fewer short commuter trips, more long airport trips), indicating a demand composition change rather than pure volume loss.",
