      "refute_if": "Both avg_trip_distance and avg_total_amount on 2024-11-28 are within 5% of the prior-Thursday average."
    },
    {
      "id": "H4",
      "kind": "data_quality",
      "statement": "The drop is an artifact of missing or incomplete TLC data for 2024-11-28.",
      "support_if": "Trip count is implausibly low (e.g., <10% of baseline) or avg_total_amount / avg_trip_distance are NULL, suggesting partial upload.",
      "refute_if": "All three metrics are present and trips are only moderately lower (consistent with a real holiday effect)."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Return trips, avg_total_amount, avg_trip_distance for 2024-11-28 and the three prior Thursdays (2024-11-07, 2024-11-14, 2024-11-21) from whybot.yellow_daily.",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Check whybot.us_holidays for holiday_name and is_national on 2024-11-28 and the three prior Thursdays.",
      "tables": [
        "whybot.us_holidays"
      ]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Fetch prcp_mm, snow_mm, tmax_c, tmin_c for 2024-11-28 and the three prior Thursdays from whybot.nyc_weather_daily.",
      "tables": [
        "whybot.nyc_weather_daily"
      ]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compare avg_trip_distance and avg_total_amount on 2024-11-28 vs. the mean of the three prior Thursdays (already returned by H0 query).",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Validate data completeness: confirm non-NULL trips, avg_total_amount, avg_trip_distance for 2024-11-28 and prior Thursdays (covered by H0 query).",
      "tables": [
        "whybot.yellow_daily"
      ]
    }
  ],
  "rationale": "H0 quantifies the drop. H1 confirms Thanksgiving as the calendar driver. H2 rules in/out weather. H3 checks whether the trip mix changed (fare/distance). H4 guards against data-quality artifacts. All queries are single-table, aggregated, and stay inside the 2024-04-01..2025-02-28 window."
}

{
  "sql": "SELECT trip_date, trips, avg_total_amount, avg_trip_distance FROM whybot.yellow_daily WHERE trip_date IN (DATE '2024-11-07', DATE '2024-11-14', DATE '2024-11-21', DATE '2024-11-28') ORDER BY trip_date",
  "tables_used": ["whybot.yellow_daily"],
  "note": "Returns one row per requested Thursday, ordered chronologically."
}

